  ['the balance knocks the']: 'テンプがアンクルを',
  ['fork; the STONE slides up']: '叩く；爪石が引き面を',
  ['the draw face and SHOVES']: '滑り上がり、車を',
  ['the wheel backward']: '後ろへ押しやる',
  ['p &lt; 0.04 of the beat']: 'p &lt; 振動の 0.04',
  ['3 · impulse']: '3 · 衝撃',
  ['the one phase the WHEEL']: '車が導く唯一の相：',
  ['leads: the tooth pays its']: '歯が押しを衝撃面へ',
  ['push into the impulse']: '注ぎ込む —',
